import{_ as o,o as r,c as a,a2 as s}from"./chunks/framework.Buc7gXeZ.js";const q=JSON.parse('{"title":"إدارة صلاحيات الموظفين","description":"","frontmatter":{},"headers":[],"relativePath":"ar/user-guide/permissions.md","filePath":"ar/user-guide/permissions.md"}'),n={name:"ar/user-guide/permissions.md"};function e(i,t,l,d,u,g){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="إدارة-صلاحيات-الموظفين" tabindex="-1">إدارة صلاحيات الموظفين <a class="header-anchor" href="#إدارة-صلاحيات-الموظفين" aria-label="Permalink to &quot;إدارة صلاحيات الموظفين&quot;">​</a></h1><p>دليل عملي لإداري النظام: إزاي تدّي موظف صلاحية يشوف/يستخدم حاجة معيّنة في النظام، وإزاي تسحبها منه.</p><h2 id="الفكرة-الأساسية" tabindex="-1">الفكرة الأساسية <a class="header-anchor" href="#الفكرة-الأساسية" aria-label="Permalink to &quot;الفكرة الأساسية&quot;">​</a></h2><p>صلاحيات أي موظف في TagERP <strong>مش بتتحدد له شخصيًا</strong> — هي نتيجة تلقائية لـ ٥ حاجات محددة في ملفه الوظيفي:</p><ol><li><strong>الشركة</strong> اللي بيشتغل فيها</li><li><strong>الفرع</strong> اللي بيشتغل فيه</li><li><strong>الإدارة</strong> اللي تابعلها</li><li><strong>الوظيفة</strong> (اللقب الوظيفي)</li><li><strong>الدرجة الوظيفية</strong></li></ol><p>يعني عشان تدّي حد صلاحية، مش هتدور على &quot;شاشة صلاحيات&quot; وتحدد له إيه يشوف وإيه لأ — <strong>هتظبط بياناته الوظيفية دي</strong>، والنظام بيحسب الباقي لوحده تلقائيًا. لو موظف اتنقل من إدارة المشتريات لإدارة المالية، صلاحياته بتتغيّر تلقائيًا في نفس اللحظة، من غير ما حد يعدّل حاجة إضافية.</p><h2 id="البُعدين-اللي-بيتحددوا" tabindex="-1">البُعدين اللي بيتحددوا <a class="header-anchor" href="#البُعدين-اللي-بيتحددوا" aria-label="Permalink to &quot;البُعدين اللي بيتحددوا&quot;">​</a></h2><p>كل موظف بيتحدد له بُعدين منفصلين تمامًا، ولازم الاتنين يتظبطوا صح:</p><h3 id="١-أنهي-بيانات-هيشوفها-النطاق" tabindex="-1">١. أنهي بيانات هيشوفها (النطاق) <a class="header-anchor" href="#١-أنهي-بيانات-هيشوفها-النطاق" aria-label="Permalink to &quot;١. أنهي بيانات هيشوفها (النطاق)&quot;">​</a></h3><p>بيتحدد بحقلين وقت إضافة/تعديل الموظف:</p><table tabindex="0"><thead><tr><th>الحقل</th><th>القيم المتاحة</th><th>معناها</th></tr></thead><tbody><tr><td><strong>نطاق الشركة</strong></td><td>سجلاته هو بس / فرعه بس / شركته كلها / شركته والشركات التابعة لها</td><td>لو موظف عادي، غالبًا &quot;فرعه بس&quot;. لو مدير قطاع على مستوى المجموعة، &quot;شركته والشركات التابعة&quot;</td></tr><tr><td><strong>نطاق الإدارة</strong></td><td>سجلاته هو بس / إدارته بس / إدارته والإدارات الفرعية التابعة لها / كل الإدارات</td><td>لو مدير إدارة، غالبًا &quot;إدارته والإدارات الفرعية التابعة لها&quot;</td></tr></tbody></table><p><strong>مثال عملي:</strong> مدير مالي في الشركة الأم، نطاق الشركة عنده &quot;شركته والتابعة لها&quot; ونطاق الإدارة &quot;إدارته والفرعية&quot; → هيشوف بيانات القطاع المالي في <strong>كل</strong> شركات المجموعة. نفس المدير لو كان في شركة تابعة (وليدة)، ونطاق الشركة عنده &quot;شركته كلها&quot; بس (مش والتابعة) → هيشوف بيانات القطاع المالي في <strong>شركته هو بس</strong>، مش في باقي شركات المجموعة.</p><h3 id="٢-أنهي-شاشات-هيقدر-يفتحها-الصلاحيات-الوظيفية" tabindex="-1">٢. أنهي شاشات هيقدر يفتحها (الصلاحيات الوظيفية) <a class="header-anchor" href="#٢-أنهي-شاشات-هيقدر-يفتحها-الصلاحيات-الوظيفية" aria-label="Permalink to &quot;٢. أنهي شاشات هيقدر يفتحها (الصلاحيات الوظيفية)&quot;">​</a></h3><p>دي بتتحدد تلقائيًا من <strong>الإدارة</strong> و<strong>الوظيفة</strong> و<strong>الدرجة</strong> اللي الموظف تابعلهم. مش بتتحدد للموظف شخصيًا.</p><ul><li>موظف تابع لإدارة <strong>المالية</strong> → هيقدر يفتح موديول المالية تلقائيًا. لو مش تابع لها، مش هيقدر يفتحه خالص.</li><li>لقب وظيفي زي &quot;محاسب عام&quot; ليه صلاحيات معينة (زي عرض القيود) تسري على أي حد شايل نفس اللقب.</li><li>بعض الصلاحيات مربوطة بالدرجة كمان — مثلاً &quot;محاسب عام&quot; درجة <strong>senior</strong> يقدر يعتمد (post) القيد، لكن نفس اللقب درجة junior مايقدرش، رغم إن الاتنين بيشوفوا نفس الشاشة.</li></ul><h2 id="إزاي-تدّي-موظف-صلاحية" tabindex="-1">إزاي تدّي موظف صلاحية <a class="header-anchor" href="#إزاي-تدّي-موظف-صلاحية" aria-label="Permalink to &quot;إزاي تدّي موظف صلاحية&quot;">​</a></h2><ol><li>افتح شاشة <strong>الموظفين</strong> (HR ← إدارة الموظفين).</li><li>أضف الموظف (أو افتح ملفه لو موجود) واختار: <ul><li>الشركة والفرع اللي بيشتغل فيهم</li><li>الإدارة التابع لها</li><li>الوظيفة (اللقب الوظيفي)</li><li>الدرجة الوظيفية</li><li>نطاق الشركة ونطاق الإدارة (زي الجدول فوق)</li></ul></li><li>احفظ. الصلاحيات بتتفعّل <strong>فورًا</strong> — مفيش خطوة إضافية ولا وقت انتظار.</li></ol><p><strong>لو الوظيفة أو الإدارة أو الدرجة اللي محتاجها مش موجودة في القوائم؟</strong> لازم تتضاف الأول من شاشاتها الخاصة (الهيكل التنظيمي ← الإدارات / الوظائف / الدرجات الوظيفية) قبل ما تقدر تختارها للموظف.</p><h2 id="إزاي-تسحب-صلاحية-من-موظف" tabindex="-1">إزاي تسحب صلاحية من موظف <a class="header-anchor" href="#إزاي-تسحب-صلاحية-من-موظف" aria-label="Permalink to &quot;إزاي تسحب صلاحية من موظف&quot;">​</a></h2><p>فيه ٣ طرق حسب الموقف:</p><table tabindex="0"><thead><tr><th>الموقف</th><th>الحل</th></tr></thead><tbody><tr><td><strong>الموظف مش شغال خالص دلوقتي</strong> (إجازة مؤقتة/إيقاف)</td><td>غيّر حالته لـ <strong>&quot;موقوف&quot;</strong> — بيفقد كل صلاحياته فورًا، وترجعله تاني لما تحطه &quot;نشط&quot;</td></tr><tr><td><strong>الموظف انتهى عقده/استقال نهائيًا</strong></td><td>غيّر حالته لـ <strong>&quot;منتهي الخدمة&quot;</strong> — نفس الأثر، دائم</td></tr><tr><td><strong>الموظف باقي شغال بس محتاج صلاحيات أقل/مختلفة</strong></td><td>غيّر وظيفته/إدارته/درجته لللي يناسب الوضع الجديد — الصلاحيات بتتحدث تلقائيًا فورًا مع الحفظ</td></tr></tbody></table><p>⚠️ <strong>مهم:</strong> حذف الموظف من الشاشة مش الطريقة الصح لسحب صلاحياته — استخدم دايمًا &quot;موقوف&quot;/&quot;منتهي الخدمة&quot; عشان يفضل تاريخه محفوظ.</p><h2 id="أسئلة-شائعة" tabindex="-1">أسئلة شائعة <a class="header-anchor" href="#أسئلة-شائعة" aria-label="Permalink to &quot;أسئلة شائعة&quot;">​</a></h2><p><strong>سؤال: عايز موظف يشوف كل حاجة في القطاع المالي بس مش يقدر يعدّل حاجة؟</strong> ده بيترتب على <strong>الوظيفة</strong> اللي هيتحطلها — لازم يكون فيه لقب وظيفي معرّف مسبقًا بصلاحية &quot;عرض بس&quot;. لو مش موجود، اطلب من فريق التطوير/الإدارة يضيفوه.</p><p><strong>سؤال: عايز أدّي مدير صلاحية يشوف فرعين بالذات، مش كل الشركة؟</strong> النظام الحالي بيدعم &quot;فرعه بس&quot; أو &quot;الشركة كلها&quot; — مفيش خيار &quot;فرعين محددين&quot; لسه. لو محتاجها فعليًا، بلّغ فريق التطوير.</p><p><strong>سؤال: عملت التعديل بس الموظف لسه شايف/مش شايف الشاشة القديمة؟</strong> اتأكد إن الموظف عمل تسجيل خروج ودخول تاني — أو استنى شوية، الصلاحيات بتتحدث فورًا في قاعدة البيانات لكن المتصفح ممكن يكون محتفظ بنسخة قديمة من القائمة الجانبية.</p><p><strong>سؤال: فيه حد معاه صلاحية مش المفروض تكون معاه، وأنا متأكد إني ظبطت بياناته صح؟</strong> دي حالة نادرة بس ممكن تحصل لو حد عدّل صلاحيات الوظيفة نفسها مباشرة من غير ما يحفظ بيانات الموظف. بلّغ فريق التطوير يشغّل أمر &quot;مطابقة الصلاحيات&quot; (<code>hr:permissions:reconcile</code>) اللي بيكتشف ويصلّح أي فرق تلقائيًا.</p>',27)])])}const p=o(n,[["render",e]]);export{q as __pageData,p as default};
